<?php require 'db.php';$q=trim($_GET['search']??'');if($q==='')$s=$pdo->query("SELECT id,room_name,building,floor,capacity,status FROM rooms ORDER BY building,room_name");else{$s=$pdo->prepare("SELECT id,room_name,building,floor,capacity,status FROM rooms WHERE room_name ILIKE :q OR building ILIKE :q OR CAST(floor AS TEXT) ILIKE :q ORDER BY building,room_name");$s->execute([':q'=>"%$q%"]);}echo json_encode(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);?>